"""Concurrent dict implementations: striped locking vs. one global lock.

Both expose the same tiny API:

    get(key, default=None) -> value
    put(key, value)        -> None
    delete(key)            -> None (raises KeyError if absent)

Keys must be hashable. Striping uses hash(key) % stripes; Python's hash is
consistent within a process, which is all we need (per-process striping only
has to be stable for the lifetime of the object).
"""

import threading


class GlobalDict:
    """Dict guarded by a single global lock."""

    def __init__(self):
        self._lock = threading.Lock()
        self._map = {}

    def get(self, key, default=None):
        with self._lock:
            return self._map.get(key, default)

    def put(self, key, value):
        with self._lock:
            self._map[key] = value

    def delete(self, key):
        with self._lock:
            try:
                del self._map[key]
            except KeyError:
                raise KeyError(key) from None

    def items(self):
        """Consistent snapshot of the whole map (for verification/tests)."""
        with self._lock:
            return dict(self._map)

    def __len__(self):
        with self._lock:
            return len(self._map)


class StripedDict:
    """Dict split into N shards, each guarded by its own lock.

    A key maps to exactly one stripe via hash(key) % stripes, so ops on
    different stripes never contend.
    """

    def __init__(self, stripes=16):
        self.stripes = max(1, int(stripes))
        self._locks = [threading.Lock() for _ in range(self.stripes)]
        self._maps = [{} for _ in range(self.stripes)]

    def _stripe_of(self, key):
        return hash(key) % self.stripes

    def get(self, key, default=None):
        i = self._stripe_of(key)
        with self._locks[i]:
            return self._maps[i].get(key, default)

    def put(self, key, value):
        i = self._stripe_of(key)
        with self._locks[i]:
            self._maps[i][key] = value

    def delete(self, key):
        i = self._stripe_of(key)
        with self._locks[i]:
            try:
                del self._maps[i][key]
            except KeyError:
                raise KeyError(key) from None

    def stripe_count(self, key):
        """Which stripe would this key land in? (exposed for tests)"""
        return self._stripe_of(key)

    def items(self):
        """Consistent snapshot: lock stripes one at a time, merge."""
        out = {}
        for i in range(self.stripes):
            with self._locks[i]:
                out.update(self._maps[i])
        return out

    def __len__(self):
        n = 0
        for i in range(self.stripes):
            with self._locks[i]:
                n += len(self._maps[i])
        return n

