import threading, time, zlib, random
from striped_dict import StripedDict, GlobalDict

def bench(d, n_ops, hot=64, payload=None):
    keys=[("hot",i) for i in range(hot)]
    for i,k in enumerate(keys): d.put(k, i)
    rng=random.Random(1)
    def work(tid):
        for _ in range(n_ops):
            k=keys[rng.randrange(hot)]
            r=rng.random()
            if r<0.6:
                if payload is not None:
                    blob=d.get(k)  # decompresses INSIDE lock
                    _ = len(blob)
                else:
                    d.get(k)
            elif r<0.9:
                d.put(k, payload or 42)
            else:
                try: d.delete(k)
                except KeyError: pass
                d.put(k, payload or 42)
    b=threading.Barrier(9); ts=[]
    t0=time.perf_counter()
    for t in range(8):
        th=threading.Thread(target=lambda: (b.wait(), work(t))); ts.append(th); th.start()
    b.wait()
    for th in ts: th.join()
    return 8*n_ops/(time.perf_counter()-t0)

BLOB = bytes(random.Random(7).randrange(256) for _ in range(4096))

