    def get(self,k,d=None):
        with self._lock:
            if k in self._map: return zlib.decompress(self._map[k])
            return d
    def put(self,k,v): 
        with self._lock: self._map[k]=zlib.compress(v)

class CmpStriped(StripedDict):
    def get(self,k,d=None):
        i=self._stripe_of(k)
        with self._locks[i]:
            m=self._maps[i]
            if k in m: return zlib.decompress(m[k])
            return d
    def put(self,k,v):
        i=self._stripe_of(k)
        with self._locks[i]: self._maps[i][k]=zlib.compress(v)

